<script setup lang="ts">import{computed,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{chapters}from'../data/chapters';import{useAppStore}from'../stores/app';import EmmaPortrait from'../components/EmmaPortrait.vue';import{Languages,Volume2,ScrollText,X,ChevronRight}from'@lucide/vue';const route=useRoute(),router=useRouter(),store=useAppStore(),idx=ref(0),log=ref(false);const chapter=computed(()=>chapters.find(c=>c.id===Number(route.params.id))||chapters[0]);const lines=computed(()=>chapter.value.scene.dialogues);const line=computed(()=>lines.value[idx.value]);const fill=(s:string)=>s.replaceAll('{{name}}',store.s.name);function next(){if(idx.value<lines.value.length-1)idx.value++;else router.push(`/choice/${chapter.value.id}`)}</script>
<template><section class="conversation"><header><button @click="router.push('/story')"><X/></button><span>CHAPTER {{chapter.id}}</span><div><button @click="store.toggleTranslation"><Languages/></button><button @click="log=true"><ScrollText/></button></div></header><div class="scene-label">International Share House · {{chapter.theme}}</div><EmmaPortrait :expression="line.expression||'normal'" :src="chapter.image" full/><div class="dialog-box" @click="next"><div class="speaker">{{line.speaker==='Emma'?'Emma Mizuki':store.s.name}}</div><button class="sound" @click.stop><Volume2/></button><h2>{{fill(line.english)}}</h2><p v-if="store.s.showTranslation">{{fill(line.japanese)}}</p><span class="continue">TAP TO CONTINUE <ChevronRight/></span></div><div v-if="log" class="modal" @click.self="log=false"><div class="log-card"><button class="modal-close" @click="log=false"><X/></button><h2>Conversation log</h2><div v-for="(d,i) in lines.slice(0,idx+1)" :key="i"><b>{{d.speaker==='Emma'?'Emma':store.s.name}}</b><p>{{fill(d.english)}}</p><small>{{fill(d.japanese)}}</small></div></div></div></section></template>
